from attr import define, field, validators
from attr.validators import disabled

@define
class C:
    x: int = field(validator=validators.instance_of(int))

def test_nested_disabled():
    with disabled():
        with disabled():
            pass
        # BUG: validators are now ENABLED even though we're still in the outer disabled()
        try:
            C(x="not_int")
        except TypeError:
            assert False, "TypeError raised unexpectedly: validators were re-enabled"

def test_override_disabled():
    from attr._config import set_run_validators
    set_run_validators(False)
    with disabled():
        pass
    # BUG: validators are now ENABLED even though they were disabled before the context manager
    try:
        C(x="not_int")
    except TypeError:
        assert False, "TypeError raised unexpectedly: validators were re-enabled"

if __name__ == "__main__":
    try:
        test_nested_disabled()
        test_override_disabled()
        print("REPRO PASS")
    except Exception as e:
        print(f"REPRO FAIL: {e}")
EOF

